window.RP_SESSION={"id":"S-204e40b14e93","messages":[{"id":"RP-III-0121835","time":"2026-07-19T21:57:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":["P-e6655a038328"]},{"id":"RP-III-0121836","time":"2026-07-19T22:00:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"네가 어느날 찾아왔다. 따스한 봄. 높은 산 위 위치한 점성탑에 [웃음]을 지으며 찾아왔다. 너는 산을 오르면서 따온 산 딸기들을 잔뜩 들고 옷에는 흙먼지를 잔뜩 뒤집은 채로 찾아왔다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121837","time":"2026-07-19T22:01:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 항상 갑작스럽다. 너는 손을 내밀었다. 여행을 같이 가자고 이야기 했다. 함께 하는 모험이 점성탑보다 더 재미있을거라고 이야기했다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121838","time":"2026-07-19T22:01:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 너무 끈질겼다. 마음에 든 것은 꼭 얻겠다는 마음으로. 미워할 수 없는 미소를 지으며 활기차게 이야기하고. 모두에게 사랑받을 행동을 하는 너는 너무나도 끈질겼다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121839","time":"2026-07-19T22:02:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 항상 설레인다. 매번 있을 의뢰를 이야기 하면서 어느 곳으로 갈 수 있을지 이야기한다. 함께 모험을 떠나면서 북부, 남부, 서부, 혼란스러웠던 동부.","characters":["P-e6655a038328"]},{"id":"RP-III-0121840","time":"2026-07-19T22:03:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 항상 긍정적이었다. 북부에서 조난당해 추위에 떨 때도, 사막을 건너는 중 모래 폭풍을 만났을 때도, 남부에서 마차가 무너졌을 때도, 동부에서 크나큰 불길이 다가올 때도.","characters":["P-e6655a038328"]},{"id":"RP-III-0121841","time":"2026-07-19T22:04:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 항상 자유로웠다. 모두가 공포와 무력함에 도망치려고 했지만 너는 그 감정에 자유로웠다. 너는 밝은 미소를 지으며 단지 조금 어려울 모험일 뿐이라고. 우정의 힘과 함께 한다는 의지라면 뭐든지 할 수 있다고.","characters":["P-e6655a038328"]},{"id":"RP-III-0121842","time":"2026-07-19T22:05:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 정의로웠고, 모험과 자유를 사랑했고, 세상을 구했으며. 다른 사람의 삶의 대부분에 많은 영향을 끼쳤다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121843","time":"2026-07-19T22:05:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 세상을 구했다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121844","time":"2026-07-19T22:05:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너는 모두에게 칭송 받는다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121845","time":"2026-07-19T22:05:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"하지만","characters":["P-e6655a038328"]},{"id":"RP-III-0121846","time":"2026-07-19T22:06:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너도 힘들었어. 다른 사람들은 잘 모르겠지.","characters":["P-e6655a038328"]},{"id":"RP-III-0121847","time":"2026-07-19T22:06:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그저 밝고 희망찬 그런 부분만 보고.","characters":["P-e6655a038328"]},{"id":"RP-III-0121848","time":"2026-07-19T22:06:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"너의 그 웃는 얼굴 뒤에 숨겨진 고됨은 누가 알아줄까?","characters":["P-e6655a038328"]},{"id":"RP-III-0121849","time":"2026-07-19T22:06:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"적어도 나라면....","characters":["P-e6655a038328"]},{"id":"RP-III-0121850","time":"2026-07-19T22:06:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"...","characters":["P-e6655a038328"]},{"id":"RP-III-0121851","time":"2026-07-19T22:07:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"스텔라는 꿈을 꿨다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121852","time":"2026-07-19T22:07:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아직도 선명한 그녀의 기억.","characters":["P-e6655a038328"]},{"id":"RP-III-0121853","time":"2026-07-19T22:07:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"위로를 위해 뻗은 손은 그저 방 천장을 향하고 있었다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121854","time":"2026-07-19T22:09:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"12년동안 길드에 남아 이렇게 있던 이유. 단지 그녀가 돌아올 곳을 마련해주기 위해서.","characters":["P-e6655a038328"]},{"id":"RP-III-0121855","time":"2026-07-19T22:10:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"나는 과연 정말로 네가 원하는 그런 곳을 간직하고 있는걸까?\"","characters":["P-e6655a038328"]},{"id":"RP-III-0121856","time":"2026-07-19T22:11:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"최근 길드의 상황을 생각해본다. 클램시는 항상 이야기했다. 모험가라는 것은 항상 자유와 낭만과 모험을 즐겨야한다고.","characters":["P-e6655a038328"]},{"id":"RP-III-0121857","time":"2026-07-19T22:12:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"최근의 길드를 생각해보면 솔직히 말해서 그 부분과 많이 벗어난 느낌이 있다는 것은 분명 스텔라 스스로도 잘 알고 있는 사실이다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121858","time":"2026-07-19T22:13:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"길드원들이 많아지면서 자연스럽게 개개인에 대한 통제를 하고 뭔가 사건들에 대해서 외교적인 문제가 발생할 수 있는 것을은 항상 제한하고.","characters":["P-e6655a038328"]},{"id":"RP-III-0121859","time":"2026-07-19T22:13:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"마치 새장 속의 새처럼. 자유를 잃어가는 모험가들을 만들고 있는 것이다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121860","time":"2026-07-19T22:13:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"모험이 아닌 단순히 돈을 벌기 위해서 그저 움직이는 용병과 다를바 없는 이야기.","characters":["P-e6655a038328"]},{"id":"RP-III-0121861","time":"2026-07-19T22:14:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"클램시, 너는 어떻게 생각할까?\"","characters":["P-e6655a038328"]},{"id":"RP-III-0121862","time":"2026-07-19T22:14:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"스텔라는 심란한 마음으로.","characters":["P-e6655a038328"]},{"id":"RP-III-0121863","time":"2026-07-19T22:15:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"생각을 계속한다.","characters":["P-e6655a038328"]},{"id":"RP-III-0121864","time":"2026-07-19T22:15:00+09:00","room":"RP III","name":"스텔라 스타라이트 / 기억 속 클램시","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e6655a038328"]},{"id":"RP-III-0121865","time":"2026-07-19T22:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
